{
  "inputs": [
    {
      "id": "brand-api-key",
      "type": "promptString",
      "description": "Your Variel project API key (bsk_…) to connect an existing brand. Get it from your Variel dashboard, or run `variel-mcp login` to provision one via browser sign-in (no copy-paste). You can also start keyless and generate a brand with generate_brand_kickoff.",
      "password": true
    },
    {
      "id": "anthropic-api-key",
      "type": "promptString",
      "description": "Anthropic API key. Required only for grade_visual_quality, generate_component, and Tier-2 validate_copy. Optional for all other tools.",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@variel/mcp-server@0.1.0"
      ],
      "env": {
        "BRAND_API_KEY": "${input:brand-api-key}",
        "VARIEL_API_URL": "<variel-api-url>",
        "ANTHROPIC_API_KEY": "${input:anthropic-api-key}"
      }
    }
  }
}
